css:
@import url("https://fonts.googleapis.com/css2?family=Gelasio:wght@500;700&family=Gantari:wght@400;500;700&display=swap");
:root{--pl:#3D2C4F;--pl2:#2C1F3A;--mn:#2A9D8F;--yl:#F6C453;--pa:#F4F1F8;--ink:#221A2C;--gr:#5E5669;--ln:#E0DAE8;--h:"Gelasio",Georgia,serif;--b:"Gantari",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:18px;line-height:1.6;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:700;margin:0;line-height:1.1}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--yl);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--yl);outline-offset:2px}
.hero{background:var(--pl);color:#fff;padding-bottom:70px}.nav{display:flex;justify-content:space-between;align-items:center;height:76px;position:relative}.logo{font-family:var(--h);font-size:22px;text-decoration:none}.logo span{color:var(--yl)}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none}.menu a:hover{color:var(--yl)}.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;border-radius:10px;font-size:20px;cursor:pointer}
.hg{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:start;padding-top:40px}.hg>div,.hg>form{min-width:0}
.tag{display:inline-block;background:var(--mn);border-radius:30px;padding:4px 14px;font-weight:700;font-size:15px;margin-bottom:14px}
.hero h1{font-size:clamp(40px,5.4vw,70px)}.hero p{font-size:20px;color:#D8CFE3;margin:18px 0 22px;max-width:30em}
.when{background:var(--pl2);border-radius:20px;padding:20px;margin-top:10px}.when label{display:block;font-size:15px;color:#D8CFE3;margin-bottom:6px}.when select{width:100%;font:17px var(--b);padding:11px;border-radius:12px;border:0;margin-bottom:12px}
.when .lt{font-family:var(--h);font-size:28px;color:var(--yl)}.when small{display:block;color:#D8CFE3}
.cd{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}.cd div{background:var(--pl);border-radius:12px;padding:8px 12px;text-align:center;min-width:70px}.cd b{display:block;font-size:24px}.cd span{font-size:13px;color:#D8CFE3}
.reg{background:#fff;color:var(--ink);border-radius:24px;padding:26px}.reg h2{font-size:28px}.seats{margin:8px 0 16px;font-weight:700;color:#B3261E}.seats .bar{height:8px;background:var(--pa);border-radius:8px;overflow:hidden;margin-top:6px}.seats .bar i{display:block;height:100%;background:var(--mn)}
.reg label{display:block;font-weight:500;font-size:15px;margin-bottom:6px}.reg input,.reg select{width:100%;font:17px var(--b);padding:11px;border:2px solid var(--ln);border-radius:12px;margin-bottom:14px;color:var(--ink);background:#fff}
.btn{display:inline-block;background:var(--yl);color:var(--ink);text-decoration:none;font:700 17px var(--b);padding:14px 24px;border-radius:40px;border:0;cursor:pointer}.btn.w{width:100%;text-align:center}.btn.m{background:var(--mn);color:#fff}
.done{margin-top:12px;background:var(--pa);border-radius:16px;padding:14px}.done p{margin:0 0 10px}
section{padding:80px 0}.sh{max-width:640px;margin-bottom:28px}.sh h2{font-size:clamp(32px,4.2vw,50px);color:var(--pl)}.sh p{color:var(--gr);margin:10px 0 0}
.ag ol{list-style:none;padding:0;margin:0;counter-reset:s;display:grid;grid-template-columns:1fr 1fr;gap:14px}.ag li{counter-increment:s;background:var(--pa);border-radius:18px;padding:20px 22px;display:grid;grid-template-columns:56px 1fr;gap:14px}
.ag li:before{content:counter(s);width:48px;height:48px;border-radius:14px;background:var(--pl);color:var(--yl);display:grid;place-items:center;font-family:var(--h);font-size:22px}.ag h3{font-size:21px}.ag p{margin:4px 0 0;color:var(--gr);font-size:16px}.ag .m{font-size:14px;color:var(--mn);font-weight:700}
.sp{background:var(--pa)}.spg{display:grid;grid-template-columns:300px 1fr;gap:40px;align-items:center}.spg img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:50% 50% 24px 24px}.spg h2{font-size:clamp(30px,3.8vw,44px);color:var(--pl)}.spg .r{color:var(--mn);font-weight:700;margin:6px 0 12px}
.faq .wrap{max-width:820px}.faq details{border-bottom:1px solid var(--ln);padding:16px 0}.faq summary{font-weight:700;font-size:19px;cursor:pointer}.faq p{margin:8px 0 0;color:var(--gr)}
footer{background:var(--pl2);color:#B9AFC6;padding:26px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:900px){.hg,.spg{grid-template-columns:1fr}.ag ol{grid-template-columns:1fr}.spg img{max-width:260px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:76px;left:0;right:0;background:var(--pl2);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const W=new Date('2026-10-28T17:00:00Z');
const Z=[["Europe/London","London"],["America/New_York","New York"],["America/Chicago","Chicago"],["America/Los_Angeles","Los Angeles"],["Europe/Berlin","Berlin"],["Asia/Dubai","Dubai"],["Asia/Kolkata","Mumbai"],["Asia/Singapore","Singapore"],["Australia/Sydney","Sydney"]];
let mine;try{mine=Intl.DateTimeFormat().resolvedOptions().timeZone}catch(e){mine='Europe/London'}if(!Z.some(z=>z[0]===mine))Z.unshift([mine,'Your time zone ('+mine.split('/').pop().replace('_',' ')+')']);
$('tz').innerHTML=Z.map(z=>`<option value="${z[0]}" ${z[0]===mine?'selected':''}>${z[1]}</option>`).join('');
function tz(){const z=$('tz').value;$('lt').textContent=W.toLocaleTimeString('en-GB',{timeZone:z,hour:'numeric',minute:'2-digit',hour12:true});$('ld').textContent=W.toLocaleDateString('en-GB',{timeZone:z,weekday:'long',day:'numeric',month:'long'})+', 60 minutes'}
$('tz').onchange=tz;tz();
function cd(){const s=Math.max(0,Math.floor((W-new Date())/1000));$('cD').textContent=Math.floor(s/86400);$('cH').textContent=Math.floor(s%86400/3600);$('cM').textContent=Math.floor(s%3600/60)}cd();setInterval(cd,30000);
let left=63;const cap=500;function seats(){$('st').textContent=`Only ${left} of ${cap} seats left`;$('sb').style.width=(cap-left)/cap*100+'%'}seats();
const p=d=>d.toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';const E=new Date(W.getTime()+3600e3);
$('ics').href='data:text/calendar;charset=utf-8,'+encodeURIComponent(`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Shopkeeper School//EN\r\nBEGIN:VEVENT\r\nUID:cashflow-2026@example\r\nDTSTAMP:${p(new Date())}\r\nDTSTART:${p(W)}\r\nDTEND:${p(E)}\r\nSUMMARY:Cash flow for small shops (webinar)\r\nDESCRIPTION:Join link will be emailed to you.\r\nEND:VEVENT\r\nEND:VCALENDAR`);
$('rf').onsubmit=e=>{e.preventDefault();left=Math.max(0,left-1);seats();$('dt').textContent=`You're in, ${$('rn').value}! We've sent the joining link to ${$('re').value}. It starts at ${$('lt').textContent} your time.`;$('dn').hidden=false};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
